import { NextRequest, NextResponse } from "next/server";
import { AssetLibraryService } from "@/app/services/asset-library-service";

const assetLibraryService = new AssetLibraryService();

export async function GET(request: NextRequest) {
    try {
        const mediaTypeParam = request.nextUrl.searchParams.get("mediaType");
        const search = request.nextUrl.searchParams.get("search") || undefined;
        const albumId = request.nextUrl.searchParams.get("albumId") || undefined;
        const mediaType = mediaTypeParam === "image" || mediaTypeParam === "video" || mediaTypeParam === "model"
            ? mediaTypeParam
            : undefined;

        const assets = assetLibraryService.listAssets({
            mediaType,
            search,
            albumId,
        });

        return NextResponse.json({
            ok: true,
            assets,
        });
    } catch (error) {
        const message = error instanceof Error ? error.message : "Unknown asset error";

        return NextResponse.json(
            {
                ok: false,
                error: message,
            },
            { status: 500 },
        );
    }
}